    var res = knapsackDFS(&wgt, &val, n, cap);
    std.debug.print("不超过背包容量的最大物品价值为 {}\n", .{res});

    // 记忆搜索
    var mem = [_][cap + 1]i32{[_]i32{-1} ** (cap + 1)} ** (n + 1);
    res = knapsackDFSMem(&wgt, &val, @constCast(&mem), n, cap);
    std.debug.print("不超过背包容量的最大物品价值为 {}\n", .{res});

